CREATE TABLE demo (
  id INT PRIMARY KEY,
  val TEXT
);

INSERT INTO demo (id, val)
SELECT g, md5(random()::text)
FROM generate_series(1, 5) g;

SELECT id, val FROM demo;

DROP TABLE demo;

SELECT EXISTS (
  SELECT 1 
  FROM information_schema.tables 
  WHERE table_name = 'demo'
) AS demo_table_exists;

SELECT productid, name, description, imageurl, priceusd, category 
FROM products 
LIMIT 20;

SELECT orderid, userid, TO_CHAR(orderdate, 'YYYY-MM-DD HH24:MI:SS') AS orderdate, shippingaddressid, paymentid, totalamountusd, orderstatus 
FROM orders 
LIMIT 20;

