DROP TABLE loyalty_programs;

CREATE TABLE demo (
    id integer PRIMARY KEY,
    val text
);

INSERT INTO demo (id, val)
SELECT
    i,
    md5(random()::text)
FROM generate_series(1, 5) AS i;

SELECT * FROM demo;

DROP TABLE demo;

CREATE TABLE demo (
  id integer PRIMARY KEY,
  val text
);

INSERT INTO demo (id, val)
SELECT i, md5(random()::text)
FROM generate_series(1, 5) AS i;

SELECT * FROM demo;

DROP TABLE demo;

SELECT EXISTS (
  SELECT 1
  FROM information_schema.tables
  WHERE table_schema = 'public'
    AND table_name = 'demo'
) AS demo_table_exists;

